package com.mis.mis_backend.grade;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/grades") public class GradeController{private final GradeService s;public GradeController(GradeService s){this.s=s;}@GetMapping public List<Grade> getAll(){return s.getAll();}@PostMapping public Grade create(@RequestBody Grade x){return s.create(x);}}